namespace WebSharperWebsite

open System
open System.IO
open System.Reflection
open System.Text.Json
open WebSharper
open WebSharper.UI
open WebSharper.UI.Html

/// The Bindings page. Its data comes from `bindings.json`, which is generated by
/// `scripts/extract-bindings.fsx` (run it to refresh versions, library ranges and
/// sample links) and embedded into the assembly. Reordering cards or changing the
/// categories is therefore a JSON change, not a code change.
module Bindings =

    type LibraryBinding =
        {
            Name: string
            Package: string
            Version: string
            Library: string
            LibraryVersion: string
            Description: string
            Repo: string
            Category: string
            Website: string option
            LatestVersion: string option
            Status: string option
            SampleUrl: string option
            SampleLabel: string option
        }

    type BrowserBinding =
        {
            Name: string
            Package: string
            Version: string
            Description: string
            Repo: string
            Category: string
            Website: string option
        }

    type BindingsData =
        {
            GeneratedAt: string
            Libraries: LibraryBinding list
            BrowserApis: BrowserBinding list
        }

    // ------------------------------------------------------------------
    // Loading
    // ------------------------------------------------------------------

    /// Reads `bindings.json` from the assembly manifest resources. The resource
    /// name is `<RootNamespace>.bindings.json`; we search by suffix so the
    /// namespace can change without breaking the page.
    let private readResourceText () =
        let asm = Assembly.GetExecutingAssembly()
        let name =
            asm.GetManifestResourceNames()
            |> Array.tryFind (fun n -> n.EndsWith("bindings.json", StringComparison.OrdinalIgnoreCase))
        match name with
        | None ->
            failwith "bindings.json was not embedded as a resource. Run scripts/extract-bindings.fsx and rebuild."
        | Some name ->
            use stream = asm.GetManifestResourceStream(name)
            use reader = new StreamReader(stream)
            reader.ReadToEnd()

    let private tryPropString (el: JsonElement) (name: string) =
        match el.TryGetProperty name with
        | true, v when v.ValueKind = JsonValueKind.String -> Some(v.GetString())
        | _ -> None

    let private propString (el: JsonElement) (name: string) =
        tryPropString el name |> Option.defaultValue ""

    let private parseLibrary (el: JsonElement) =
        {
            Name = propString el "name"
            Package = propString el "package"
            Version = propString el "version"
            Library = propString el "library"
            LibraryVersion = propString el "libraryVersion"
            Description = propString el "description"
            Repo = propString el "repo"
            Category = propString el "category"
            Website = tryPropString el "website"
            LatestVersion = tryPropString el "latestVersion"
            Status = tryPropString el "status"
            SampleUrl = tryPropString el "sampleUrl"
            SampleLabel = tryPropString el "sampleLabel"
        }

    let private parseBrowser (el: JsonElement) =
        {
            Name = propString el "name"
            Package = propString el "package"
            Version = propString el "version"
            Description = propString el "description"
            Repo = propString el "repo"
            Category = propString el "category"
            Website = tryPropString el "website"
        }

    let private parse (json: string) =
        use doc = JsonDocument.Parse(json)
        let root = doc.RootElement
        let libraries =
            match root.TryGetProperty "libraries" with
            | true, arr when arr.ValueKind = JsonValueKind.Array ->
                [ for el in arr.EnumerateArray() -> parseLibrary el ]
            | _ -> []
        let browserApis =
            match root.TryGetProperty "browserApis" with
            | true, arr when arr.ValueKind = JsonValueKind.Array ->
                [ for el in arr.EnumerateArray() -> parseBrowser el ]
            | _ -> []
        {
            GeneratedAt = propString root "generatedAt"
            Libraries = libraries
            BrowserApis = browserApis
        }

    let private data = lazy (readResourceText () |> parse)

    let private libraries = (data.Value).Libraries
    let private browserApis = (data.Value).BrowserApis

    // ------------------------------------------------------------------
    // Grouping
    // ------------------------------------------------------------------

    /// Groups items by category, keeping the order in which each category first
    /// appears in the JSON so the page ordering follows the script's catalog.
    let private groupByCategory (category: 'a -> string) (items: 'a list) =
        items
        |> List.fold
            (fun (acc: (string * 'a list) list) item ->
                let key = category item
                let rec add =
                    function
                    | [] -> [ (key, [ item ]) ]
                    | (k, vs) :: rest when k = key -> (k, vs @ [ item ]) :: rest
                    | (k, vs) :: rest -> (k, vs) :: add rest
                add acc)
            []

    /// URL-safe id for a category heading, e.g. "Charts & visualization" -> "charts-visualization".
    let private slug (text: string) =
        let sb = Text.StringBuilder()
        let mutable lastDash = false
        for c in text.ToLower() do
            if Char.IsLetterOrDigit c then
                sb.Append(c) |> ignore
                lastDash <- false
            elif not lastDash then
                sb.Append('-') |> ignore
                lastDash <- true
        sb.ToString().Trim('-')

    // ------------------------------------------------------------------
    // Rendering
    // ------------------------------------------------------------------

    let private nugetUrl (package: string) = "https://www.nuget.org/packages/" + package

    let private sectionHeader (title: string) (count: int) =
        div
            [ attr.``class`` "flex flex-wrap items-baseline gap-x-3 gap-y-1" ]
            [
                h3
                    [ attr.``class`` "text-lg font-semibold tracking-tight text-gray-950 dark:text-white" ]
                    [ text title ]
                span
                    [ attr.``class`` "rounded-full bg-gray-100 px-2.5 py-0.5 font-mono text-[11px] font-medium text-gray-600 dark:bg-white/5 dark:text-gray-300" ]
                    [ text (string count) ]
            ]

    let private grid (cards: Doc list) =
        div
            [ attr.``class`` "mt-4 grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3" ]
            cards

    /// A row of pill links that jump to each category section.
    let private categoryNav (groups: (string * 'a list) list) =
        groups
        |> List.map (fun (category, items) ->
            a
                [
                    attr.``class`` "inline-flex items-center gap-1.5 rounded-full border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-600 transition duration-300 hover:border-gray-300 hover:text-gray-900 dark:border-gray-800 dark:bg-gray-900 dark:text-gray-300 dark:hover:border-gray-700 dark:hover:text-white"
                    attr.href ("#" + slug category)
                ]
                [
                    text category
                    span
                        [ attr.``class`` "text-gray-400 dark:text-gray-500" ]
                        [ text (string items.Length) ]
                ])
        |> Doc.Concat

    let private boundVersionText (version: string) =
        if version.Contains "unpinned" then "latest" else version

    let private statusInfo (status: string option) =
        match status with
        | Some "up-to-date" -> "Up to date", "up-to-date"
        | Some "recent" -> "Recent", "recent"
        | _ -> "", ""

    let private libraryCard (b: LibraryBinding) =
        let label, key = statusInfo b.Status
        Templates.BindingsTemplate.LibraryCard()
            .Name(b.Name)
            .PackageName(b.Package)
            .PackageVersion(b.Version)
            .VersionAttr(Attr.Create "data-nuget-package" b.Package)
            .Description(b.Description)
            .BoundVersion(boundVersionText b.LibraryVersion)
            .LatestVersion(defaultArg b.LatestVersion "—")
            .StatusLabel(label)
            .StatusAttr(if key = "" then attr.hidden "" else Attr.Create "data-status" key)
            .WebsiteUrl(defaultArg b.Website "#")
            .WebsiteAttr(if b.Website.IsSome then Attr.Empty else attr.hidden "")
            .NuGetUrl(nugetUrl b.Package)
            .SourceUrl(b.Repo)
            .SampleUrl(defaultArg b.SampleUrl "")
            .SampleLabel(defaultArg b.SampleLabel "Sample")
            .SampleAttr(if b.SampleUrl.IsSome then Attr.Empty else attr.hidden "")
            .Doc()

    let private browserCard (b: BrowserBinding) =
        Templates.BindingsTemplate.BrowserCard()
            .Name(b.Name)
            .PackageName(b.Package)
            .PackageVersion(b.Version)
            .VersionAttr(Attr.Create "data-nuget-package" b.Package)
            .Description(b.Description)
            .WebsiteUrl(defaultArg b.Website "#")
            .WebsiteAttr(if b.Website.IsSome then Attr.Empty else attr.hidden "")
            .NuGetUrl(nugetUrl b.Package)
            .SourceUrl(b.Repo)
            .Doc()

    let private libraryGroups () = libraries |> groupByCategory (fun b -> b.Category)
    let private browserGroups () = browserApis |> groupByCategory (fun b -> b.Category)

    let private librarySections () =
        libraryGroups ()
        |> List.map (fun (category, items) ->
            section
                [
                    attr.``class`` "mt-14 scroll-mt-28"
                    attr.id (slug category)
                    Attr.Create "data-binding-section" ""
                ]
                [
                    sectionHeader category items.Length
                    grid (items |> List.map libraryCard)
                ])
        |> Doc.Concat

    let private browserSections () =
        browserGroups ()
        |> List.map (fun (category, items) ->
            section
                [
                    attr.``class`` "mt-14 scroll-mt-28"
                    attr.id (slug category)
                    Attr.Create "data-binding-section" ""
                ]
                [
                    sectionHeader category items.Length
                    grid (items |> List.map browserCard)
                ])
        |> Doc.Concat

    let BindingsDoc () =
        Templates.BindingsTemplate.Content()
            .LibraryCount(string libraries.Length)
            .BrowserCount(string browserApis.Length)
            .LibraryCategoryNav(categoryNav (libraryGroups ()))
            .BrowserCategoryNav(categoryNav (browserGroups ()))
            .LibrarySections(librarySections ())
            .BrowserSections(browserSections ())
            .Doc()
